// Danh sách đơn hàng mặc định
const DEFAULT_ORDERS = [];

/**
 * Lớp EbookDB quản lý LocalStorage và phát thông báo BroadcastChannel
 */
class EbookDB {
  static broadcastChannel = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('ebookpe_sync_channel') : null;

  static notifyChange(type, payload = {}) {
    if (this.broadcastChannel) {
      try {
        this.broadcastChannel.postMessage({ type, payload, timestamp: Date.now() });
      } catch (e) {
        console.warn('BroadcastChannel error:', e);
      }
    }
  }

  // --- CÀI ĐẶT ---
  static getSettings() {
    try {
      const data = localStorage.getItem(STORAGE_KEYS.SETTINGS);
      if (!data) {
        localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(DEFAULT_SETTINGS));
        return DEFAULT_SETTINGS;
      }
      const parsed = JSON.parse(data);
      // Tự động đồng bộ số tài khoản và thông tin mới nếu là số demo cũ
      if (parsed.accountNumber === '0988889999' || parsed.accountName === 'NGUYEN VAN ADMIN') {
        const synced = { ...parsed, ...DEFAULT_SETTINGS };
        localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(synced));
        return synced;
      }
      return { ...DEFAULT_SETTINGS, ...parsed };
    } catch (e) {
      return DEFAULT_SETTINGS;
    }
  }

  static saveSettings(settings) {
    const updated = { ...this.getSettings(), ...settings };
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(updated));
    this.notifyChange('SETTINGS_UPDATED', updated);
    if (window.EbookSupabase && typeof window.EbookSupabase.saveSettings === 'function') {
      window.EbookSupabase.saveSettings(updated).catch(err => {
        console.warn('[EbookDB] Lỗi đồng bộ cài đặt lên Cloud:', err);
      });
    }
    return updated;
  }

  // --- EBOOK ---
  static getBooks() {
    if (window._cloudBooksCache && Array.isArray(window._cloudBooksCache) && window._cloudBooksCache.length > 0) {
      return window._cloudBooksCache;
    }
    const REAL_DRIVE_URL = '';
    try {
      const data = localStorage.getItem(STORAGE_KEYS.BOOKS);
      if (data === null) {
        localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(DEFAULT_BOOKS));
        window._cloudBooksCache = DEFAULT_BOOKS.slice();
        return DEFAULT_BOOKS;
      }
      let parsed = JSON.parse(data);
      if (Array.isArray(parsed) && parsed.length > 0) {
        let changed = false;
        parsed = parsed.map(b => {
          if (!b.downloadUrl || b.downloadUrl === '#' || b.downloadUrl.includes('example')) {
            b.downloadUrl = REAL_DRIVE_URL;
            changed = true;
          }
          return b;
        });
        if (changed) {
          localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(parsed));
        }
        window._cloudBooksCache = parsed;
        return parsed;
      }
      localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(DEFAULT_BOOKS));
      window._cloudBooksCache = DEFAULT_BOOKS.slice();
      return DEFAULT_BOOKS;
    } catch (e) {
      window._cloudBooksCache = DEFAULT_BOOKS.slice();
      return DEFAULT_BOOKS;
    }
  }

  static getBookById(id) {
    const books = this.getBooks();
    return books.find(b => b.id === id) || null;
  }

  static saveBook(book) {
    const books = this.getBooks();
    let updated;
    const existingIndex = books.findIndex(b => b.id === book.id);
    if (existingIndex >= 0) {
      books[existingIndex] = { ...books[existingIndex], ...book, updatedAt: new Date().toISOString() };
      updated = books[existingIndex];
    } else {
      const newBook = {
        ...book,
        id: book.id || 'ebk-' + Date.now().toString(36),
        createdAt: book.createdAt || new Date().toISOString(),
        rating: book.rating || 5.0,
        reviewsCount: book.reviewsCount || 1,
        salesCount: book.salesCount || 0,
        status: book.status || 'active'
      };
      books.unshift(newBook);
      updated = newBook;
    }
    window._cloudBooksCache = books;
    try {
      localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(books));
    } catch (storageErr) {
      console.warn('LocalStorage error while saving book:', storageErr);
      try {
        // If storage is full due to heavy coverImage base64, save without image payload
        if (updated.coverImage && updated.coverImage.length > 50000) {
          const fallbackBooks = books.map(b => b.id === updated.id ? { ...b, coverImage: '' } : b);
          localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(fallbackBooks));
        }
      } catch (err2) {
        console.error('Critical localStorage error:', err2);
      }
    }
    this.notifyChange('BOOKS_UPDATED', { books });

    // Tự động đẩy lên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.saveBook === 'function') {
      window.EbookSupabase.saveBook(updated).catch(e => console.warn('Supabase saveBook sync error:', e));
    }

    return updated;
  }

  static deleteBook(id) {
    let books = this.getBooks();
    books = books.filter(b => b.id !== id);
    window._cloudBooksCache = books;
    try {
      localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(books));
    } catch (e) {
      console.warn('LocalStorage deleteBook error:', e);
    }
    this.notifyChange('BOOKS_UPDATED', { books });

    // Tự động xóa trên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.deleteBook === 'function') {
      window.EbookSupabase.deleteBook(id).catch(e => console.warn('Supabase deleteBook sync error:', e));
    }

    return true;
  }

  static clearAllBooks() {
    window._cloudBooksCache = [];
    try {
      localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify([]));
    } catch (e) {
      console.warn('LocalStorage clearAllBooks error:', e);
    }
    this.notifyChange('BOOKS_UPDATED', { books: [] });

    // Tự động xóa sạch trên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.clearAllBooks === 'function') {
      window.EbookSupabase.clearAllBooks().catch(e => console.warn('Supabase clearAllBooks sync error:', e));
    }
  }

  // --- COMBOS ---
  static getCombos() {
    if (window._cloudCombosCache && Array.isArray(window._cloudCombosCache) && window._cloudCombosCache.length > 0) {
      // Filter out any legacy ghost combos from cache if present
      const cleanCache = window._cloudCombosCache.filter(c => 
        c.id !== 'combo-khoi-nghiep-tinh-gon' && 
        c.id !== 'combo-mindset-tai-chinh' &&
        c.id !== 'combo-vip' &&
        !(c.title === 'Combo Khởi Nghiệp Tinh Gọn' && c.price === 179000) &&
        !(c.title === 'Combo Mindset & Đột Phá Tài Chính' && c.price === 159000)
      );
      if (cleanCache.length !== window._cloudCombosCache.length) {
        window._cloudCombosCache = cleanCache.length > 0 ? cleanCache : DEFAULT_COMBOS.slice();
        try { localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(window._cloudCombosCache)); } catch (e) {}
      }
      return window._cloudCombosCache;
    }
    const REAL_DRIVE_URL = '';
    try {
      const data = localStorage.getItem(STORAGE_KEYS.COMBOS);
      if (data === null) {
        localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(DEFAULT_COMBOS));
        window._cloudCombosCache = DEFAULT_COMBOS.slice();
        return DEFAULT_COMBOS;
      }
      let parsed = JSON.parse(data);
      if (Array.isArray(parsed) && parsed.length > 0) {
        // Purge legacy ghost demo combos
        parsed = parsed.filter(c => 
          c.id !== 'combo-khoi-nghiep-tinh-gon' && 
          c.id !== 'combo-mindset-tai-chinh' &&
          c.id !== 'combo-vip' &&
          !(c.title === 'Combo Khởi Nghiệp Tinh Gọn' && c.price === 179000) &&
          !(c.title === 'Combo Mindset & Đột Phá Tài Chính' && c.price === 159000)
        );
        if (parsed.length === 0) {
          parsed = DEFAULT_COMBOS.slice();
        }
        let changed = false;
        parsed = parsed.map(c => {
          if (!c.downloadUrl || c.downloadUrl === '#' || c.downloadUrl.includes('example')) {
            c.downloadUrl = REAL_DRIVE_URL;
            changed = true;
          }
          const def = DEFAULT_COMBOS.find(d => d.id === c.id);
          if (def && (!c.bookIds || c.bookIds.length === 0 || (c.bookIds[0] && c.bookIds[0].includes('ebk-khoi-nghiep-0')))) {
            c.bookIds = def.bookIds;
            c.bookNames = def.bookNames;
            c.bonusList = def.bonusList;
            changed = true;
          }
          return c;
        });
        localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(parsed));
        window._cloudCombosCache = parsed;
        return parsed;
      }
      localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(DEFAULT_COMBOS));
      window._cloudCombosCache = DEFAULT_COMBOS.slice();
      return DEFAULT_COMBOS;
    } catch (e) {
      window._cloudCombosCache = DEFAULT_COMBOS.slice();
      return DEFAULT_COMBOS;
    }
  }

  static getComboById(id) {
    const combos = this.getCombos();
    return combos.find(c => c.id === id) || null;
  }

  static saveCombo(combo) {
    const combos = this.getCombos();
    let updated;
    const existingIndex = combos.findIndex(c => c.id === combo.id);
    if (existingIndex >= 0) {
      combos[existingIndex] = { ...combos[existingIndex], ...combo, updatedAt: new Date().toISOString() };
      updated = combos[existingIndex];
    } else {
      const newCombo = {
        ...combo,
        id: combo.id || 'combo-' + Date.now().toString(36),
        createdAt: combo.createdAt || new Date().toISOString(),
        status: combo.status || 'active'
      };
      combos.unshift(newCombo);
      updated = newCombo;
    }
    window._cloudCombosCache = combos;
    try {
      localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(combos));
    } catch (err) {
      console.warn('LocalStorage saveCombo error:', err);
    }
    this.notifyChange('COMBOS_UPDATED', { combos });

    // Tự động đẩy lên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.saveCombo === 'function') {
      window.EbookSupabase.saveCombo(updated).catch(e => console.warn('Supabase saveCombo sync error:', e));
    }

    return updated;
  }

  static deleteCombo(id) {
    let combos = this.getCombos();
    combos = combos.filter(c => c.id !== id);
    window._cloudCombosCache = combos;
    localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(combos));
    this.notifyChange('COMBOS_UPDATED', { combos });

    // Tự động xóa trên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.deleteCombo === 'function') {
      window.EbookSupabase.deleteCombo(id).catch(e => console.warn('Supabase deleteCombo sync error:', e));
    }

    return true;
  }

  static clearAllCombos() {
    window._cloudCombosCache = [];
    localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify([]));
    this.notifyChange('COMBOS_UPDATED', { combos: [] });

    // Tự động xóa sạch trên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.clearAllCombos === 'function') {
      window.EbookSupabase.clearAllCombos();
    }
  }

  // --- ĐƠN HÀNG ---
  static secureLinks = null;
  static saveSecureLinks(links) { this.secureLinks = links; }
  static getSecureLinks() { return this.secureLinks; }

  static getOrders() {
    try {
      const data = localStorage.getItem(STORAGE_KEYS.ORDERS);
      if (!data) {
        localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify([]));
        return [];
      }
      const parsed = JSON.parse(data);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  static createOrder(orderData) {
    const orders = this.getOrders();
    const newOrder = {
      orderId: 'EBPE-' + Math.floor(100000 + Math.random() * 900000),
      orderDate: new Date().toLocaleString('vi-VN'),
      status: 'completed',
      ...orderData
    };
    orders.unshift(newOrder);
    localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(orders));
    this.notifyChange('ORDERS_UPDATED', { order: newOrder });

    // Tăng lượt mua cho từng cuốn sách
    if (newOrder.items && newOrder.items.length) {
      const books = this.getBooks();
      newOrder.items.forEach(item => {
        const book = books.find(b => b.id === item.id);
        if (book) {
          book.salesCount = (book.salesCount || 0) + (item.qty || 1);
        }
      });
      localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(books));
      this.notifyChange('BOOKS_UPDATED', { books });
    }

    // Tự động đẩy đơn hàng lên Supabase Cloud Database (nếu có cấu hình)
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.saveOrder === 'function') {
      try {
        window.EbookSupabase.saveOrder(newOrder);
      } catch (e) {
        console.warn('Lỗi lưu đơn hàng Supabase:', e);
      }
    }

    return newOrder;
  }

  static updateOrderStatus(orderId, newStatus) {
    const orders = this.getOrders();
    const order = orders.find(o => o.orderId === orderId);
    if (order) {
      order.status = newStatus;
      localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(orders));
      this.notifyChange('ORDERS_UPDATED', { orders });
      if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.saveOrder === 'function') {
        window.EbookSupabase.saveOrder(order).catch(e => console.warn('Supabase updateOrderStatus sync error:', e));
      }
      return true;
    }
    return false;
  }

  static clearAllOrders() {
    localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify([]));
    this.notifyChange('ORDERS_UPDATED', { orders: [] });

    // Tự động xóa sạch trên Supabase Cloud
    if (typeof window !== 'undefined' && window.EbookSupabase && typeof window.EbookSupabase.clearAllOrders === 'function') {
      window.EbookSupabase.clearAllOrders();
    }
  }

  // --- GIỎ HÀNG (CART) ---
  static getCart() {
    try {
      const data = localStorage.getItem(STORAGE_KEYS.CART);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  static saveCart(cart) {
    localStorage.setItem(STORAGE_KEYS.CART, JSON.stringify(cart));
    this.notifyChange('CART_UPDATED', { cart });
  }

  static addToCart(item) {
    const cart = this.getCart();
    const existingIndex = cart.findIndex(i => i.id === item.id);
    if (existingIndex >= 0) {
      cart[existingIndex].qty = (cart[existingIndex].qty || 1) + 1;
    } else {
      cart.push({ ...item, qty: 1 });
    }
    this.saveCart(cart);
    return cart;
  }

  static removeFromCart(id) {
    let cart = this.getCart();
    cart = cart.filter(i => i.id !== id);
    this.saveCart(cart);
    return cart;
  }

  static clearCart() {
    this.saveCart([]);
  }

  // --- KHÔI PHỤC VÀ BACKUP ---
  static resetToDefault() {
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(DEFAULT_SETTINGS));
    localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(DEFAULT_BOOKS));
    localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(DEFAULT_COMBOS));
    localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(DEFAULT_ORDERS));
    localStorage.setItem(STORAGE_KEYS.CART, JSON.stringify([]));
    if (typeof window !== 'undefined') {
      window._cloudBooksCache = DEFAULT_BOOKS.slice();
      window._cloudCombosCache = DEFAULT_COMBOS.slice();
    }
    this.notifyChange('RESET_ALL');
  }

  static exportBackupJSON() {
    return JSON.stringify({
      version: '2.0',
      timestamp: new Date().toISOString(),
      settings: this.getSettings(),
      books: this.getBooks(),
      combos: this.getCombos(),
      orders: this.getOrders()
    }, null, 2);
  }

  static importBackupJSON(jsonStr) {
    try {
      const data = JSON.parse(jsonStr);
      if (data.books && Array.isArray(data.books)) {
        localStorage.setItem(STORAGE_KEYS.BOOKS, JSON.stringify(data.books));
        if (typeof window !== 'undefined') window._cloudBooksCache = data.books.slice();
      }
      if (data.orders && Array.isArray(data.orders)) {
        localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(data.orders));
      }
      if (data.settings) {
        localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(data.settings));
      }
      if (data.combos && Array.isArray(data.combos)) {
        localStorage.setItem(STORAGE_KEYS.COMBOS, JSON.stringify(data.combos));
        if (typeof window !== 'undefined') window._cloudCombosCache = data.combos.slice();
      }
      this.notifyChange('IMPORT_SUCCESS');
      return { success: true };
    } catch (e) {
      return { success: false, error: e.message };
    }
  }

  // Tiện ích format tiền VNĐ
  static formatVND(amount) {
    const num = typeof amount === 'number' ? amount : (parseInt(String(amount || '').replace(/\D/g, ''), 10) || 0);
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(num).replace('₫', 'đ');
  }
}

// Gán biến toàn cục để các script khác sử dụng dễ dàng
window.EbookDB = EbookDB;
window.DEFAULT_CATEGORIES = DEFAULT_CATEGORIES;

// Khởi tạo cache ngay lập tức từ LocalStorage để không bị trễ khi tải trang
try {
  const initBooksRaw = localStorage.getItem(STORAGE_KEYS.BOOKS);
  if (initBooksRaw) {
    const initBooks = JSON.parse(initBooksRaw);
    if (Array.isArray(initBooks) && initBooks.length > 0) {
      window._cloudBooksCache = initBooks;
    }
  }
  const initCombosRaw = localStorage.getItem(STORAGE_KEYS.COMBOS);
  if (initCombosRaw) {
    const initCombos = JSON.parse(initCombosRaw);
    if (Array.isArray(initCombos) && initCombos.length > 0) {
      window._cloudCombosCache = initCombos;
    }
  }
} catch (e) {}
